_WT_SKIP = {".git", ".claude", "node_modules", "__pycache__", ".wrangler"}


def ls_worktree(root):
    """path (relative to the VV app root, '/'-separated) -> 'WT:<absolute path>' for every file on disk, pruning
    .claude/worktrees, node_modules and the AUDIT evidence folder (none of them is app code)."""
    res = {}
    for dp, dn, fn in os.walk(root):
        rel_dir = os.path.relpath(dp, root).replace(os.sep, "/")
        dn[:] = [d for d in dn if d not in _WT_SKIP and not (rel_dir == "." and d.startswith("ValeVision__AUDIT__"))]
        for f in fn:
            p = f if rel_dir == "." else rel_dir + "/" + f
            res[p] = "WT:" + os.path.join(dp, f)
    return res


def check_index_is_w0_02_only():
    out = run(["git", "-C", VCB, "diff", "--cached", "-M", "--name-status", "-z"]).split(b"\0")
    kinds = collections.Counter()
    i = 0
    while i < len(out):
        rec = out[i]
        if not rec:
            i += 1
            continue
        k = rec.decode()
        if k.startswith("R") or k.startswith("C"):
            kinds[k[0] + ("100" if k[1:] == "100" else k[1:])] += 1
            i += 3
        else:
            kinds[k] += 1
            i += 2
    return dict(kinds)


# -----------------------------------------------------------------------------
# Export resolution
# -----------------------------------------------------------------------------
class Exports:
    """Export names of a module in one tree, following `export * from`. Modules outside the
    parsed app set (vendor files) are read from the tree's own blobs on demand."""

    def __init__(self, parsed, tree=None, repo=None, prefix_note="", transform=None):
        self.parsed = parsed          # path -> parse_module result
        self.tree = tree or {}        # path -> blob sha (the same tree the parsed set came from)
        self.repo = repo
        self.transform = transform
        self.cache = {}
        self.loaded_on_demand = []

    def _load(self, path):
        if path in self.parsed:
            return True
        if path not in self.tree or not is_module(path):
            return False
        if str(self.tree[path]).startswith("WT:"):
            blob = open(self.tree[path][3:], "rb").read()
        elif not self.repo:
            return False
        else:
            blob = cat_blobs(self.repo, [self.tree[path]])[self.tree[path]]
        txt = decode(blob)
        if self.transform:
            txt = self.transform(txt)
        self.parsed[path] = parse_source(txt)
        self.loaded_on_demand.append(path)
        return True

    def of(self, path, seen=None):
        if path in self.cache:
            return self.cache[path]
        if not self._load(path):
            return None
        seen = set() if seen is None else seen
        if path in seen:
            return set()
        seen.add(path)
        p = self.parsed[path]
        names = set(p["exports"])
        for spec in p["star_from"]:
            kind, tgt = resolve_spec(path, spec, {})
            if kind == "internal":
                sub = self.of(tgt, seen)
                if sub:
                    names |= (sub - {"default"})
        self.cache[path] = names
        return names


