def norm_tv_source(s):
    m = re.match(r"^(\S+)(?:\s+\((.*)\))?\s*$", s.strip())
    p, ann = m.group(1), (m.group(2) or "")
    if p.startswith("TVM/"):
        return SRC + p[4:], ann
    if p.startswith("TV/"):
        return p[3:], ann
    return None, ann


def norm_vv_target(s):
    s2 = s.strip()
    new = "(new)" in s2
    if "->" in s2:
        s2 = s2.split("->", 1)[1].strip()
    p = s2.split()[0]
    if p.startswith("VVM/"):
        return SRC + p[4:], new
    if p.startswith("VV/"):
        return p[3:], new
    return None, new


# Take mode of every (package, TV JS source) whose VV target is NOT a new file, decided from the
# package's own goal / vv_adaptations / tv_sources annotation (read by hand, 01-Oct-2026).
# whole       = TV's file at the pin taken whole, VV seams re-applied (R3/K3 R3)
